INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Bestandsaufnahme immer Softwareänderungen voraussetzt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Analyse, keine Änderung"}, {"text": "Ja", "correct": false, "because": "Erfassen vor Ändern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt gehört zur Erfassung eines Systems?', 3, '[{"text": "Dokumentation", "correct": true, "because": "Erfasst Ist-Zustand"}, {"text": "Programmierung", "correct": false, "because": "Änderung, keine Analyse"}, {"text": "Design", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente prüft man bei einer Systembewertung?', 5, '[{"text": "Hardware", "correct": true, "because": "Teil des Systems"}, {"text": "Software", "correct": true, "because": "Funktionalität prüfen"}, {"text": "Prozesse", "correct": true, "because": "Abläufe analysieren"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ziel ist der Ist-Zustand. b) Sie führt direkt zu Änderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Änderungen folgen später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein IT-System untersuche?', 4, '[{"text": "Netzwerkstruktur", "correct": false, "because": "Teil der Analyse"}, {"text": "Softwareversionen", "correct": false, "because": "Wichtig für Bewertung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Bestandsaufnahme immer automatisch läuft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Manuell möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel durchführbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte bei der Erfassung eines Systems helfen?', 3, '[{"text": "Netzwerkscanner", "correct": true, "because": "Erfasst Geräte"}, {"text": "Texteditor", "correct": false, "because": "Nur Dokumentation"}, {"text": "Grafiksoftware", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Bewertung eines Ist-Zustands?', 5, '[{"text": "Schwachstellen finden", "correct": true, "because": "Probleme erkennen"}, {"text": "Optimierungspotenzial", "correct": true, "because": "Verbesserungen planen"}, {"text": "Transparenz", "correct": true, "because": "Übersicht schaffen"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Prozesse analysiert werden und b) nur Hardware zählt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Software wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein System zu erfassen?', 4, '[{"text": "Dokumentation", "correct": false, "because": "Erfasst Ist-Zustand"}, {"text": "Inventarliste", "correct": false, "because": "Übersicht Hardware"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Bestandsaufnahme Änderungen umsetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Analyse"}, {"text": "Ja", "correct": false, "because": "Umsetzung folgt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte helfen bei der Systembewertung?', 4, '[{"text": "Hardware prüfen", "correct": true, "because": "Teil der Analyse"}, {"text": "Prozesse dokumentieren", "correct": true, "because": "Abläufe verstehen"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Bestandsaufnahme nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs profitieren"}, {"text": "Ja", "correct": false, "because": "Universell nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Erfassung eines Systems?', 3, '[{"text": "Ist-Zustand verstehen", "correct": true, "because": "Basis für Planung"}, {"text": "Design verbessern", "correct": false, "because": "Kein Ziel"}, {"text": "Kosten erhöhen", "correct": false, "because": "Effizienz ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerke werden analysiert. b) Nur Software zählt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Hardware wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Dokumentation bei der Analyse?', 4, '[{"text": "Ist-Zustand festhalten", "correct": true, "because": "Basis für Planung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Anderer Zweck"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Bewertung immer Änderungen vorschlägt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Analyse möglich"}, {"text": "Ja", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Systembewertung nützlich?', 5, '[{"text": "Transparenz", "correct": true, "because": "Übersicht schaffen"}, {"text": "Schwachstellen", "correct": true, "because": "Probleme erkennen"}, {"text": "Optimierung", "correct": true, "because": "Verbesserungen planen"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
